# Copyright (c) 2026
"""Bounded Context disclosure for exact-name Python function retrieval."""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from typing import TYPE_CHECKING, ClassVar

if TYPE_CHECKING:
    from devtools.context.python_declarations import (
        PythonFunctionDeclarationKind,
        PythonSourceOccurrence,
    )
    from devtools.context.python_function_retrieval import (
        PythonFunctionExactNameRelevanceEvidence,
        PythonFunctionExactNameRetrievalResult,
    )

_DISCLOSURE_IDENTITY_SEMANTICS = (
    "python-function-exact-name-context-disclosure-v1"
)


@dataclass(frozen=True, slots=True)
class PythonFunctionDeclarationDisclosureItem:
    """Project established declaration knowledge into a disclosure form."""

    selected_match: PythonFunctionExactNameRelevanceEvidence
    declared_name: str
    declaration_kind: PythonFunctionDeclarationKind
    source_occurrence: PythonSourceOccurrence
    proposition: str

    REPRESENTATION: ClassVar[str] = (
        "python-function-declaration-knowledge-projection-v1"
    )


@dataclass(frozen=True, slots=True)
class PythonFunctionExactNameContextDisclosure:
    """Retain fixed all-match selection and its realized representations."""

    retrieval: PythonFunctionExactNameRetrievalResult
    selected_matches: tuple[PythonFunctionExactNameRelevanceEvidence, ...]
    items: tuple[PythonFunctionDeclarationDisclosureItem, ...]

    SELECTION: ClassVar[str] = "all-exact-name-matches-in-retrieval-order-v1"

    @property
    def identity(self) -> str:
        """Identify the bounded selection and representation deterministically."""
        return _semantic_digest(
            _DISCLOSURE_IDENTITY_SEMANTICS,
            self.SELECTION,
            PythonFunctionDeclarationDisclosureItem.REPRESENTATION,
            self.retrieval.query.declared_name,
            *(match.knowledge.identity for match in self.selected_matches),
        )


def disclose_python_function_exact_name_retrieval(
    retrieval: PythonFunctionExactNameRetrievalResult,
) -> PythonFunctionExactNameContextDisclosure:
    """Select every match and faithfully project its established knowledge."""
    selected_matches = retrieval.matches
    items = tuple(
        PythonFunctionDeclarationDisclosureItem(
            selected_match=match,
            declared_name=match.knowledge.declared_name,
            declaration_kind=match.knowledge.declaration_kind,
            source_occurrence=match.knowledge.support,
            proposition=match.knowledge.PROPOSITION,
        )
        for match in selected_matches
    )
    return PythonFunctionExactNameContextDisclosure(
        retrieval=retrieval,
        selected_matches=selected_matches,
        items=items,
    )


def _semantic_digest(semantics: str, *values: str) -> str:
    """Hash length-framed values for this bounded disclosure representation."""
    digest = hashlib.sha256()
    for value in (semantics, *values):
        encoded = value.encode("utf-8")
        digest.update(len(encoded).to_bytes(8, byteorder="big"))
        digest.update(encoded)
    return digest.hexdigest()

# Copyright (c) 2026
"""Pre-analysis Python function resource candidates from observed source.

This bounded selector filters an explicit caller-ordered set of already
observed resources. A positive result means only that the requested exact name
occurred as a stdlib-tokenizer ``NAME`` token; declaration analysis remains a
separate AST-owned operation.
"""

from __future__ import annotations

import tokenize
from dataclasses import dataclass
from io import StringIO
from typing import TYPE_CHECKING, ClassVar

if TYPE_CHECKING:
    from collections.abc import Sequence

    from devtools.context.python_function_retrieval import (
        PythonFunctionExactNameQuery,
    )
    from devtools.context.repository import (
        RepositoryResourceAddress,
        RepositoryResourceOccurrence,
        RepositorySnapshot,
        RepositorySnapshotId,
    )


class PythonFunctionCandidateTokenizationError(Exception):
    """Report a required eligible resource that could not be tokenized."""

    snapshot_id: RepositorySnapshotId
    resource_address: RepositoryResourceAddress
    tokenizer_message: str

    def __init__(
        self,
        *,
        snapshot_id: RepositorySnapshotId,
        resource_address: RepositoryResourceAddress,
        error: tokenize.TokenError | IndentationError,
    ) -> None:
        """Capture the failed resource and narrow tokenizer diagnostic."""
        self.snapshot_id = snapshot_id
        self.resource_address = resource_address
        self.tokenizer_message = str(error)
        message = (
            "Could not tokenize observed Python candidate resource "
            f"{resource_address}: {error}"
        )
        super().__init__(message)


@dataclass(frozen=True, slots=True)
class PythonFunctionNameTokenCandidateEvidence:
    """Record one exact ``NAME`` token observation within one resource."""

    token_index: int
    token_string: str

    MECHANISM: ClassVar[str] = "stdlib-generate-tokens-name-exact-equality-v1"
    NATIVE_OBSERVATION: ClassVar[str] = "exact-python-name-token-match"


@dataclass(frozen=True, slots=True)
class PythonFunctionAnalysisCandidateResource:
    """Retain one selected observed resource and all supporting token matches."""

    resource: RepositoryResourceOccurrence
    supporting_matches: tuple[PythonFunctionNameTokenCandidateEvidence, ...]


@dataclass(frozen=True, slots=True)
class PythonFunctionAnalysisCandidateSelection:
    """Retain one bounded pre-analysis candidate-selection result."""

    snapshot_id: RepositorySnapshotId
    query: PythonFunctionExactNameQuery
    eligible_resources: tuple[RepositoryResourceOccurrence, ...]
    candidates: tuple[PythonFunctionAnalysisCandidateResource, ...]

    @property
    def eligible_resource_addresses(self) -> tuple[RepositoryResourceAddress, ...]:
        """Expose every considered resource in caller-supplied order."""
        return tuple(resource.address for resource in self.eligible_resources)

    @property
    def candidate_resource_addresses(self) -> tuple[RepositoryResourceAddress, ...]:
        """Expose selected candidates in caller-supplied eligible order."""
        return tuple(candidate.resource.address for candidate in self.candidates)


def select_python_function_analysis_candidates(
    snapshot: RepositorySnapshot,
    *,
    query: PythonFunctionExactNameQuery,
    resource_addresses: Sequence[RepositoryResourceAddress],
) -> PythonFunctionAnalysisCandidateSelection:
    """Select resources containing an exact matching Python ``NAME`` token.

    Every eligible address is validated against ``snapshot`` before any source
    is tokenized. Tokenization consumes only retained decoded text. Candidate
    order follows caller-supplied eligible order; multiple matching tokens
    select one resource while all token observations remain available.
    """
    eligible_addresses = tuple(resource_addresses)
    if not eligible_addresses:
        msg = "Python function candidate selection requires at least one resource."
        raise ValueError(msg)
    if len(set(eligible_addresses)) != len(eligible_addresses):
        msg = "Python function candidate resource addresses must be distinct."
        raise ValueError(msg)

    eligible_resources = tuple(
        snapshot.resource_at(address) for address in eligible_addresses
    )
    candidates: list[PythonFunctionAnalysisCandidateResource] = []
    for resource in eligible_resources:
        try:
            supporting_matches = tuple(
                PythonFunctionNameTokenCandidateEvidence(
                    token_index=token_index,
                    token_string=token_info.string,
                )
                for token_index, token_info in enumerate(
                    tokenize.generate_tokens(StringIO(resource.content).readline),
                )
                if token_info.type == tokenize.NAME
                and token_info.string == query.declared_name
            )
        except (tokenize.TokenError, IndentationError) as error:
            raise PythonFunctionCandidateTokenizationError(
                snapshot_id=snapshot.id,
                resource_address=resource.address,
                error=error,
            ) from error
        if supporting_matches:
            candidates.append(
                PythonFunctionAnalysisCandidateResource(
                    resource=resource,
                    supporting_matches=supporting_matches,
                ),
            )

    return PythonFunctionAnalysisCandidateSelection(
        snapshot_id=snapshot.id,
        query=query,
        eligible_resources=eligible_resources,
        candidates=tuple(candidates),
    )

# Copyright (c) 2026
"""Bounded observation of explicitly addressed repository text resources.

Observation is complete for exactly the finite caller-requested collection of
UTF-8 text resources. Resources are acquired sequentially in canonical address
order; the operation makes no atomic, repository-wide, or discovery claim.
"""

from __future__ import annotations

import hashlib
import string
from dataclasses import dataclass
from pathlib import Path, PurePosixPath, PureWindowsPath
from typing import TYPE_CHECKING, ClassVar, cast

if TYPE_CHECKING:
    from collections.abc import Collection

from devtools.core.identity import Identity
from devtools.core.paths import ResolvedPath, resolve_path
from devtools.resources.filesystem import FileFormat, TextFile, read

_CONTENT_IDENTITY_SEMANTICS = "decoded-utf8-text-sha256-v1"
_SNAPSHOT_IDENTITY_SEMANTICS = "explicit-required-text-resources-sha256-v1"
_SHA256_HEX_LENGTH = 64


class RepositoryObservationError(Exception):
    """Reject an observation that cannot satisfy its declared boundary."""


@dataclass(frozen=True, slots=True)
class RepositoryId:
    """Identify one logical Repository independently of its location or state."""

    value: Identity

    @classmethod
    def new(cls) -> RepositoryId:
        """Generate a new nominal Repository identity."""
        return cls(Identity.new())

    @classmethod
    def parse(cls, value: str) -> RepositoryId:
        """Parse a Repository identity from UUID text."""
        return cls(Identity.parse(value))

    def __str__(self) -> str:
        """Return canonical UUID text."""
        return str(self.value)


@dataclass(frozen=True, slots=True)
class Repository:
    """Represent a logical software repository across changing states."""

    id: RepositoryId

    @classmethod
    def new(cls) -> Repository:
        """Create a logical Repository with a new nominal identity."""
        return cls(RepositoryId.new())


@dataclass(frozen=True, slots=True)
class RepositoryResourceAddress:
    """Represent one canonical POSIX-style path relative to a repository root."""

    value: str

    def __post_init__(self) -> None:
        """Reject empty, absolute, noncanonical, or traversing addresses."""
        if not self.value:
            msg = "Repository resource address cannot be empty."
            raise ValueError(msg)
        if "\\" in self.value:
            msg = "Repository resource address must use forward slashes."
            raise ValueError(msg)

        posix_path = PurePosixPath(self.value)
        windows_path = PureWindowsPath(self.value)
        if posix_path.is_absolute() or windows_path.drive:
            msg = "Repository resource address must be relative."
            raise ValueError(msg)

        parts = self.value.split("/")
        if any(part in {"", ".", ".."} for part in parts):
            msg = "Repository resource address must be canonical without traversal."
            raise ValueError(msg)

    @property
    def parts(self) -> tuple[str, ...]:
        """Return canonical repository-relative path components."""
        return tuple(self.value.split("/"))

    def __str__(self) -> str:
        """Return the canonical repository-relative address."""
        return self.value


@dataclass(frozen=True, slots=True)
class ContentIdentity:
    """Identify decoded UTF-8 text independently of its repository address."""

    value: str

    def __post_init__(self) -> None:
        """Validate the local SHA-256 hexadecimal representation."""
        _validate_sha256(self.value, label="Content identity")

    def __str__(self) -> str:
        """Return the local hexadecimal identity representation."""
        return self.value


@dataclass(frozen=True, slots=True)
class RepositorySnapshotId:
    """Identify state observed under this module's bounded semantics."""

    value: str

    def __post_init__(self) -> None:
        """Validate the local SHA-256 hexadecimal representation."""
        _validate_sha256(self.value, label="Repository snapshot identity")

    def __str__(self) -> str:
        """Return the local hexadecimal identity representation."""
        return self.value


@dataclass(frozen=True, slots=True)
class RepositoryResourceOccurrence:
    """Retain one addressed text occurrence and its independent content identity."""

    address: RepositoryResourceAddress
    content_identity: ContentIdentity
    content: str
    encoding: str
    byte_size: int


@dataclass(frozen=True, slots=True)
class RepositorySnapshot:
    """Represent complete state for an explicit required resource collection."""

    OBSERVATION_SEMANTICS: ClassVar[str] = _SNAPSHOT_IDENTITY_SEMANTICS

    id: RepositorySnapshotId
    repository_id: RepositoryId
    resources: tuple[RepositoryResourceOccurrence, ...]

    @property
    def resource(self) -> RepositoryResourceOccurrence:
        """Return the sole occurrence for compatible single-resource consumers."""
        if len(self.resources) != 1:
            msg = "Repository snapshot does not contain exactly one resource."
            raise ValueError(msg)
        return self.resources[0]

    def resource_at(
        self,
        address: RepositoryResourceAddress,
    ) -> RepositoryResourceOccurrence:
        """Return the observed occurrence at one exact requested address."""
        for resource in self.resources:
            if resource.address == address:
                return resource
        msg = f"Repository snapshot does not contain resource address: {address}."
        raise ValueError(msg)


def observe_repository_resource(
    *,
    repository: Repository,
    root: ResolvedPath,
    address: RepositoryResourceAddress,
) -> RepositorySnapshot:
    """Observe one required UTF-8 text resource through one bounded read.

    Success means the exact requested address resolved beneath ``root`` and was
    read completely according to :func:`devtools.resources.filesystem.read`.
    The operation does not discover other resources or claim an atomic view of
    the containing filesystem.

    :raises RepositoryObservationError: If resolution escapes the supplied root.
    :raises FilesystemError: If the required resource cannot be read completely.
    """
    return observe_repository_resources(
        repository=repository,
        root=root,
        addresses=(address,),
    )


def observe_repository_resources(
    *,
    repository: Repository,
    root: ResolvedPath,
    addresses: Collection[RepositoryResourceAddress],
) -> RepositorySnapshot:
    """Observe a finite explicit collection of required UTF-8 text resources.

    Addresses are canonicalized into repository-relative lexical order before
    sequential acquisition. Success means every distinct requested address was
    read completely. A failure raises without publishing a partial snapshot.
    Equivalent collections therefore produce equivalent state regardless of
    caller ordering or observation root, but no simultaneous filesystem view is
    claimed.

    :raises ValueError: If no addresses are supplied or an address is repeated.
    :raises RepositoryObservationError: If resolution escapes the supplied root.
    :raises FilesystemError: If any required resource cannot be read completely.
    """
    requested_addresses = tuple(addresses)
    if not requested_addresses:
        msg = "Repository observation requires at least one resource address."
        raise ValueError(msg)
    if len(set(requested_addresses)) != len(requested_addresses):
        msg = "Repository observation resource addresses must be distinct."
        raise ValueError(msg)

    ordered_addresses = tuple(
        sorted(requested_addresses, key=lambda requested: requested.value),
    )
    normalized_root = resolve_path(root.value)
    resources = tuple(
        _observe_resource(root=normalized_root, address=requested)
        for requested in ordered_addresses
    )
    snapshot_id = RepositorySnapshotId(
        _semantic_digest(
            _SNAPSHOT_IDENTITY_SEMANTICS,
            str(repository.id),
            *(
                value
                for resource in resources
                for value in (
                    str(resource.address),
                    str(resource.content_identity),
                )
            ),
        ),
    )
    return RepositorySnapshot(
        id=snapshot_id,
        repository_id=repository.id,
        resources=resources,
    )


def _observe_resource(
    *,
    root: ResolvedPath,
    address: RepositoryResourceAddress,
) -> RepositoryResourceOccurrence:
    """Acquire one required occurrence within a normalized observation root."""
    candidate = resolve_path(
        Path(*address.parts),
        base_directory=root.value,
    )
    if not candidate.value.is_relative_to(root.value):
        msg = f"Repository resource resolves outside the observation root: {address}."
        raise RepositoryObservationError(msg)

    file = cast("TextFile", read(candidate, file_format=FileFormat.TEXT))
    content_identity = ContentIdentity(
        _semantic_digest(_CONTENT_IDENTITY_SEMANTICS, file.content),
    )
    return RepositoryResourceOccurrence(
        address=address,
        content_identity=content_identity,
        content=file.content,
        encoding=file.encoding,
        byte_size=file.byte_size,
    )


def _semantic_digest(semantics: str, *values: str) -> str:
    """Hash unambiguous length-framed semantic values for this module."""
    digest = hashlib.sha256()
    for value in (semantics, *values):
        encoded = value.encode("utf-8")
        digest.update(len(encoded).to_bytes(8, byteorder="big"))
        digest.update(encoded)
    return digest.hexdigest()


def _validate_sha256(value: str, *, label: str) -> None:
    """Validate one lowercase SHA-256 hexadecimal representation."""
    if len(value) != _SHA256_HEX_LENGTH or any(
        character not in string.hexdigits for character in value
    ):
        msg = f"{label} must be a 64-character hexadecimal SHA-256 value."
        raise ValueError(msg)
    if value != value.lower():
        msg = f"{label} must use lowercase hexadecimal."
        raise ValueError(msg)

